def brand(): return '<span class="brand"><span class="mark"><svg width="26" height="26" viewBox="0 0 32 32" fill="none"><path d="m7 8 9-4 9 4-9 4-9-4Zm0 7 9 4 9-4M7 22l9 4 9-4" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg></span>Docu<i>Mind</i></span>'
def shot(name,caption,height=290):
    position = '50% 14%' if name == '08-comparison-detail' else 'top'
    if name in {'03-assistant', '03-assistant-detail', '09-operations'}:
        name = 'dark/' + name
    return f'<figure class="shot"><img src="../screenshots/{name}.png" style="height:{height}px;object-position:{position}"/><figcaption>{caption}</figcaption></figure>'
def card(n,title,body):return f'<div class="card"><div class="num">{n}</div><h3>{title}</h3><p>{body}</p></div>'
def step(n,title,body):return f'<div class="step"><b>{n}</b><div><strong>{title}</strong><p>{body}</p></div></div>'
def author_credit():
    return '<p class="author-credit">Designed &amp; Developed by <strong>Fiza Ahmad</strong></p>'

def page(n,body,dark=False):
    credit = author_credit() if n == 1 else ''
    return f'<section class="page {"dark" if dark else ""}"><header class="top">{brand()}<span>ENGINEERING CASE STUDY / PERSONAL PROJECT</span></header>{body}{credit}<footer class="footer"><span>DOCUMIND · DOCUMENT INTELLIGENCE & OPERATIONS</span><span>Fiza Ahmad</span><span>{n:02d} / 08</span></footer></section>'

def case_study():
    pages=[]
    pages.append(page(1,'''<p class="eyebrow">A personal full-stack engineering project</p><h1 class="cover-title">Engineering an<br/>enterprise AI<br/><span class="accent">document intelligence</span><br/>platform.</h1><p class="cover-deck">From scattered documents to evidence-backed answers and accountable workflows.</p><div class="flow"><span class="pill">SOURCE-LINKED INTELLIGENCE</span><span class="pill">HUMAN REVIEW</span><span class="pill">ORGANIZATION ISOLATION</span></div>'''+shot('03-assistant','Actual application · fictional documents · clearly labeled development mock; not a live GPT response.',285)+'''<p class="cover-label">DocuMind — Engineering an Enterprise AI Document Intelligence Platform</p>''',True))
    pages.append(page(2,'''<p class="eyebrow">01 / The problem and the intent</p><h2>An answer is only<br/>the beginning.</h2><p class="lead">Contracts, policies and reports carry business decisions. Finding a passage matters—but so do its source, its permissions and the action that follows.</p><p class="quote">I built DocuMind to connect document understanding with the work that comes next.</p><div class="grid three">'''+card('01','Find the evidence','Search meaning, not only filenames. Keep page and passage references attached.')+card('02','Make it reviewable','Turn fields, changes and commitments into candidates a person can inspect.')+card('03','Close the loop','Connect review, responsibility and deadlines across an organization.')+'''</div>'''+shot('01-dashboard','Organization overview populated by the real demo API. Counts describe fictional analysis records, not customer impact.',255)+'''<div class="callout"><p><strong>Scope:</strong> a personal project demonstrating production-oriented design. No claim of customers, commercial deployment or measured business impact.</p></div>'''))
    pages.append(page(3,case_architecture_section()))
    pages.append(page(4,'''<p class="eyebrow">03 / Document processing</p><h2>Reliable intelligence starts<br/>before the model call.</h2><p class="lead">Uploads return while background work turns files into source-linked, searchable content.</p><div class="split"><div>'''+step('01','Validate + store','PDF, DOCX and TXT. Scoped paths, safe names and configurable size limits.')+step('02','Extract + selectively OCR','PyMuPDF text first. Tesseract only where needed; preserve PDF page numbers.')+step('03','Chunk with context','Configurable size and overlap. Retain document, section and source offsets.')+'''</div><div>'''+step('04','Encode locally','Cached Sentence Transformer on CPU; MiniLM default, 384 dimensions.')+step('05','Persist + retrieve','pgvector cosine distance, filtered by organization and embedding profile.')+step('06','Recover safely','Leases, bounded resources and retry scheduling; prevent stale publication.')+'''</div></div>'''+shot('02-document-library','Actual document library. Six fictional documents were uploaded and indexed by the real worker for this capture.',250)+'''<p class="note">OCR is optional and disabled for this capture. Its implementation is verified in code/tests; these PDFs contain native text. These native-text portfolio captures use cached local models and mock AI; the paid GPT validation is documented on page 5.</p>'''))
    pages.append(page(5,case_ai_section()))
    pages.append(page(6,'''<p class="eyebrow">05 / Structured intelligence</p><h2>Turn passages into<br/>reviewable business records.</h2><p class="lead">Versioned templates define fields and types. Rules flag review candidates. Comparison exposes actual textual changes; optional AI can help interpret them.</p>'''+shot('05-extraction-detail','Deterministic extraction of fictional commercial terms, with source evidence and a preserved review decision.',280)+'''<div class="grid" style="margin-top:20px">'''+card('FINDINGS + COMMITMENTS','Candidates, not conclusions','Threshold rules and literal commitments produce reviewable risks and obligations. Contract deadlines remain separate from assignment dates.')+card('COMPARISON','Show the actual change','Deterministic differences work without GPT. Optional explanations are bounded to the changed source passages.')+'''</div>'''+shot('08-comparison-detail','Actual comparison between two fictional agreement documents; not a claim of legal significance.',150)))
    pages.append(page(7,'''<p class="eyebrow">06 / Enterprise workflows</p><h2>Beyond the answer:<br/>ownership and accountability.</h2><p class="lead">The same scoped evidence flows into review queues, obligation tracking, assignments, activity history and authorized exports.</p>'''+shot('09-operations','Actual organization-wide Operations screen backed by the isolated demo database.',290)+'''<div class="grid" style="margin-top:22px">'''+card('ACCESS','Identity + organization scope','Argon2id passwords, JWT access, rotating refresh sessions, HttpOnly cookies and CSRF checks. Scope is enforced again during retrieval.')+card('LIFECYCLE','Retain decisions, not stale evidence','Reprocessing creates revisions without silently overwriting reviews. Deleted/superseded sources are handled explicitly.')+card('ACCOUNTABILITY','Assignment + audit history','Organization-member assignments, separate due dates and optimistic concurrency preserve who changed what.')+card('OPERATIONS','Reports with clear semantics','Counts describe current analysis records; overlapping templates are not presented as unique business items.')+'''</div>'''))
    pages.append(page(8,'''<p class="eyebrow">07 / Engineering reflection</p><h2>What made this<br/><span class="accent">an engineering project.</span></h2><div class="grid" style="margin-top:30px">'''+card('01','Evidence has a lifecycle','Source IDs alone are not enough. Revisions, deletion and publication-time checks matter as much as retrieval.')+card('02','Recovery is part of the feature','Background extraction, indexing and analysis need leases, bounded attempts and safe publication—not only a happy path.')+card('03','AI needs explicit boundaries','Keep generation configurable. Track requests, bound context/output, and retain human review instead of claiming certainty.')+card('04','Simplicity is a tradeoff','A shared PostgreSQL worker reduces infrastructure. Exact cosine search is straightforward; scale and quality need future measurement.')+'''</div><div class="rule"></div><p class="eyebrow">Recorded implementation verification</p><div class="grid three"><div><div class="metric">73</div><p class="captionline">frontend tests passed</p></div><div><div class="metric">155</div><p class="captionline">backend tests passed<br/>1 optional integration skip</p></div><div><div class="metric">Live</div><p class="captionline">paid GPT Q&amp;A<br/>validated manually</p></div></div><p class="note">Local development: processing, retrieval and workflows tested locally. Automated verification: recorded runs shown above; providers mocked. Real API validation: the developer’s paid Q&amp;A example on page 5. No new full-suite run is claimed here.</p><div class="rule"></div><p style="font-size:17px;font-weight:650">The stack</p><p class="captionline">Next.js · React · TypeScript · Tailwind · FastAPI · SQLAlchemy · Alembic · PostgreSQL/pgvector · Sentence Transformers · PyMuPDF · Tesseract · OpenAI GPT · Docker Compose</p><p class="captionline">Personal project. Product screenshots use fictional data and labeled mock output. A separate recorded manual test validates real paid OpenAI Q&amp;A; not every AI workflow was manually validated. No additional paid calls were made for these assets.</p>''',True))
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><title>DocuMind — Engineering an Enterprise AI Document Intelligence Platform</title><style>'+CSS+'</style></head><body>'+''.join(pages)+'</body></html>'

