def slide(n,body,dark=False):
    credit = author_credit() if n == 1 else ''
    return f'<section class="slide {"dark" if dark else ""}" id="slide-{n}"><header class="top">{brand()}<span>PERSONAL ENGINEERING PROJECT</span></header>{body}{credit}<footer class="footer"><span>DOCUMIND / ENGINEERING SHOWCASE</span><span>Fiza Ahmad</span><span>{n:02d} / 08</span></footer></section>'

def carousel():
    slides=[]
    slides.append(slide(1,'''<p class="eyebrow">Built end to end</p><h1>I built<br/>DocuMind.</h1><p class="lead">An enterprise AI document intelligence<br/>and operations platform.</p>'''+shot('03-assistant-detail','Actual app · fictional documents · labeled mock response',410)+'''<div class="flow" style="margin-top:32px"><span class="pill">DOCUMENTS</span><span class="pill">EVIDENCE</span><span class="pill">WORKFLOWS</span></div><p class="captionline">Built locally. Real paid GPT validation.<br/>Evidence and workflows beyond the chatbot.</p>''',True))
    slides.append(slide(2,'''<p class="eyebrow">The problem</p><h2>The information<br/>is there.<br/>The workflow isn't.</h2><p class="lead">Documents contain decisions, deadlines and commitments. Finding an answer is only one part of using that information.</p><div style="margin-top:42px">'''+step('01','Find it','Which document actually supports the answer?')+step('02','Understand it','What changed? What needs a closer review?')+step('03','Act on it','Who owns the next step—and by when?')+'''</div><div class="callout"><p>I wanted to connect these steps in one source-linked system.</p></div>'''))
    slides.append(slide(3,'''<p class="eyebrow">The solution</p><h2>Upload. Search.<br/>Understand. Review.</h2><p class="lead">One organization workspace for documents, evidence and follow-through.</p>'''+shot('01-dashboard-detail','Real API-backed demo overview. Fictional data; no fabricated business impact.',420)+'''<div class="grid three" style="margin-top:30px">'''+card('01','Ingest','Files become searchable sources.')+card('02','Inspect','Answers and records retain evidence.')+card('03','Assign','People review and own the work.')+'''</div>'''))
    slides.append(slide(4,carousel_hybrid_section()))
    slides.append(slide(5,'''<p class="eyebrow">Document intelligence</p><h2>Useful records.<br/>Visible evidence.</h2><p class="lead">Grounded Q&A, typed extraction, rule findings, obligation candidates and comparison.</p>'''+shot('05-extraction-detail','Actual deterministic extraction. Fictional source terms.',360)+'''<div class="grid" style="margin-top:26px">'''+card('EVIDENCE','Inspect the source','Page and passage references stay attached to reviewable results.')+card('BOUNDARIES','Review candidates','Risks and obligations are not verified legal conclusions.')+'''</div><p class="note">Paid GPT Q&amp;A was manually validated. Screenshots remain mock; not every structured AI feature was manually validated.</p>'''))
    slides.append(slide(6,'''<p class="eyebrow">Beyond a chatbot</p><h2>Intelligence needs<br/>accountability.</h2><p class="lead">A result should have a source,<br/>an access boundary and a next step.</p><div class="grid" style="margin-top:40px">'''+card('ACCESS','Organizations + roles','Membership-scoped APIs and retrieval. Secure browser sessions.')+card('REVIEW','Human decisions','Approve, reject or correct. Preserve original values and history.')+card('OWNERSHIP','Assignments','Organization members, due dates and optimistic concurrency.')+card('OPERATIONS','Queues + audit','Central obligations, risk register, review queues and exports.')+'''</div><div class="callout"><p>Contract deadlines and task due dates are different things. The data model treats them that way.</p></div>'''))
    slides.append(slide(7,carousel_ai_section(),True))
    slides.append(slide(8,'''<p class="eyebrow">What I learned</p><h2>A good AI feature<br/>needs a good<br/><span style="color:#7d5bd3">data lifecycle.</span></h2><p class="lead">Authorization, recovery and review deserve the same attention as the model call.</p><div class="stack"><span>Next.js / TypeScript</span><span>Tailwind</span><span>FastAPI</span><span>SQLAlchemy / Alembic</span><span>PostgreSQL / pgvector</span><span>Sentence Transformers</span><span>PyMuPDF / Tesseract</span><span>OpenAI GPT / Responses API</span><span>Docker Compose</span></div><div class="rule"></div><h3 style="font-size:33px;letter-spacing:-.03em">I'd welcome a technical review.</h3><p class="lead" style="font-size:25px">Where would you push the design next:<br/>retrieval quality, evidence validation,<br/>or workflow boundaries?</p><p class="note" style="margin-top:28px">Recorded automated tests: 73 frontend passed; 155 backend passed, 1 optional skip. Real paid GPT Q&amp;A validated separately.<br/>Personal project · mock UI captures · repository link in the post.</p>'''))
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><title>DocuMind — Engineering Showcase</title><style>'+CSS+CAROUSEL_CSS+'</style></head><body>'+''.join(slides)+'</body></html>'

